// Output only campaign metadata, never contacts, templates, phone numbers or message content.
const items=$input.all().map(x=>x.json);
const records=items.length===1&&Array.isArray(items[0].payload)?items[0].payload:items.length===1&&Array.isArray(items[0].campaigns)?items[0].campaigns:items;
const known=[];
for(const row of records){
  if(!row||Object.keys(row).length===0)continue;
  const rawId=row.id??row.display_id;
  const id=Number(rawId);
  if(!Number.isSafeInteger(id)||id<=0)throw new Error('Chatwoot returned campaign without a valid numeric display ID');
  known.push({id,type:row.campaign_type??null,status:row.campaign_status??null,title:typeof row.title==='string'?row.title.slice(0,90):null});
}
known.sort((a,b)=>b.id-a.id);
return [{json:{mode:'READ_ONLY',campaignCount:known.length,campaigns:known,notice:known.length?'Use an existing native WhatsApp one-off campaign ID from this list in the recipient-report workflow.':'No Chatwoot campaigns found. Do not invent an ID or create a live campaign just for this test.',sendingEnabled:false}}];
